package org.eclipse.rdf4j.sail.lmdb;

/**
 * The node-predicate projection named a predicate the authoritative adjacency rows do not have.
 * <p>
 * This is structural corruption, never an ordinary miss: the projection is derived from the primary index, so a
 * predicate it lists must resolve. Skipping the predicate instead of failing would turn corruption into a silently
 * incomplete answer, which is the one outcome the adjacency layer must never produce (invariant I2 makes LMDB the
 * authority; an under-reported answer is not a fallback, it is a wrong answer).
 * <p>
 * The throw happens mid-stream, after rows have already been emitted, so it cannot be converted into a fallback: the
 * caller has consumed results that a re-run from the disk trees would produce again. It is therefore a dedicated
 * signal, distinct from the revision-gap mechanism, which lets the store degrade only this capability and schedule the
 * rebuild that restores it.
 */
final class LmdbNodePredicateInconsistencyException extends IllegalStateException {

	private static final long serialVersionUID = 1L;

	LmdbNodePredicateInconsistencyException(String message) {
		super(message);
	}
}
